import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.stream.*;


public class E {

    private static final FastReader in = new FastReader();
    private static final FastWriter out = new FastWriter();

    public static void main(String[] args) {
        new E().run();
    }

    private void run() {
        int t = 1;
        while (t-- > 0) {
            solve();
        }
        out.flush();
    }

    private void solve() {
        int n = in.nextInt();
        long kt = in.nextLong();

        if (kt >= n) {
            out.println(0);
            return;
        }

        int k = (int) kt;
        Modulo m = new Modulo(998244353);
        long[] facts = m.factorials(n);

        long ans = 0L;
        int c = n - k;
        for (int i = 0; i <= c; i++) {
            long term = m.mult(m.comb(c, i, facts), m.pow(c - i, n));
            if (i % 2 == 0) {
                ans = m.add(ans, term);
            } else {
                ans = m.sub(ans, term);
            }
        }
        ans = m.mult(ans, m.comb(n, n - k, facts));
        if (k > 0) ans = m.mult(ans, 2);
        out.println(ans);
    }

}


class FastReader {

    private static final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private StringTokenizer st;

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                return null;
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public BigDecimal nextBigDecimal() {
        return new BigDecimal(next());
    }

    public BigInteger nextBigInteger() {
        return new BigInteger(next());
    }

    public boolean nextBoolean() {
        return Boolean.parseBoolean(next());
    }

    public byte nextByte() {
        return Byte.parseByte(next());
    }

    public int[] nextIntArray(int len) {
        int[] a = new int[len];
        for (int i = 0; i < len; i++) a[i] = nextInt();
        return a;
    }

    public long[] nextLongArray(int len) {
        long[] a = new long[len];
        for (int i = 0; i < len; i++) a[i] = nextLong();
        return a;
    }

    public double[] nextDoubleArray(int len) {
        double[] a = new double[len];
        for (int i = 0; i < len; i++) a[i] = nextDouble();
        return a;
    }

}


class FastWriter extends PrintWriter {

    public FastWriter() {
        super(System.out);
    }

    public void println(boolean[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            print(i + 1 < a.length ? ' ' : '\n');
        }
    }

    public void println(double[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            print(i + 1 < a.length ? ' ' : '\n');
        }
    }

    public void println(int[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            print(i + 1 < a.length ? ' ' : '\n');
        }
    }

    public void println(long[] a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            print(i + 1 < a.length ? ' ' : '\n');
        }
    }

    public void println(Object... a) {
        for (int i = 0; i < a.length; i++) {
            print(a[i]);
            print(i + 1 < a.length ? ' ' : '\n');
        }
    }

    public <T> void println(List<T> l) {
        println(l.toArray());
    }

    public void debug(String name, Object o) {
        String value = Arrays.deepToString(new Object[]{o});
        value = value.substring(1, value.length() - 1);
        System.err.println(name + " => " + value);
    }

}


class Modulo {

    private final long mod;

    public Modulo(long mod) {
        this.mod = mod;
    }

    public long add(long a, long b) {
        long c = a + b;
        return c >= mod ? c - mod : c;
    }

    public long sub(long a, long b) {
        long c = a - b;
        return c < 0 ? c + mod : c;
    }

    public long mult(long a, long b) {
        return (a * b) % mod;
    }

    public long div(long a, long b) {
        return mult(a, pow(b, mod - 2));
    }

    public long pow(long a, long b) {
        long res = 1L;
        a %= mod;
        while (b > 0) {
            if ((b & 1L) > 0) res = (res * a) % mod;
            a = (a * a) % mod;
            b >>= 1;
        }
        return res;
    }

    public long comb(int n, int k, long[] facts) {
        if (k < 0 || k > n) return 0L;
        return mult(facts[n], mult(pow(facts[k], mod - 2), pow(facts[n - k], mod - 2)));
    }

    public long[] factorials(int n) {
        long[] f = new long[n + 1];
        f[0] = 1L;
        for (int i = 1; i <= n; i++) f[i] = (f[i - 1] * i) % mod;
        return f;
    }

}
